test('applyVoucher applies a voucher to a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER2024', amount: 5000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SUMMER2024');
  assert.equal(result.value.voucher.amount, 5000);
});

test('applyVoucher rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER2024', amount: 5000.5 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
