    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER2024', amount: 0 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
