  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER2024', amount: -1000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects voucher on non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const result = applyVoucher(issued, { code: 'SUMMER2024', amount: 5000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('applyVoucher rejects second voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SUMMER2024', amount: 5000 }).value;

  const result = applyVoucher(withVoucher, { code: 'FALL2024', amount: 3000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'VOUCHER_EXISTS');
});

test('invoiceTotals includes voucher field', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals reduces total by voucher amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const withoutVoucher = invoiceTotals(invoice);
  const voucherAmount = 5000;

  const withVoucher = invoiceTotals({
    ...invoice,
    voucher: { code: 'SUMMER2024', amount: voucherAmount },
  });

  assert.equal(withVoucher.voucher, voucherAmount);
  assert.equal(withVoucher.total, withoutVoucher.total - voucherAmount);
});

test('invoiceTotals calculation: subtotal - discount + vat - voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const withVoucher = {
    ...invoice,
    voucher: { code: 'SUMMER2024', amount: 2000 },
  };

  const totals = invoiceTotals(withVoucher);
  const expectedTotal =
    totals.subtotal - totals.discount + totals.vat - totals.voucher;

  assert.equal(totals.total, expectedTotal);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.equal(invoice.voucher, undefined);

  applyVoucher(invoice, { code: 'SUMMER2024', amount: 5000 });

  assert.equal(invoice.voucher, undefined);
});

